# restore_after_cubemx.ps1  --  ASCII only on purpose.
#
# WHY ASCII: Windows PowerShell 5.1 reads a .ps1 without a BOM using the ANSI
# code page (GBK on this machine). Non-ASCII comments get mangled into bytes
# that break the parser, and the script fails to load. Keeping this file pure
# ASCII makes it work on both Windows PowerShell 5.1 and PowerShell 7.
# (The Chinese explanation lives in AD7767升级日记/ instead.)
#
# WHAT IT FIXES
# -------------
# cmake/stm32cubemx/CMakeLists.txt is generated by CubeMX. CubeMX only knows
# about the content it generated itself, so every "GENERATE CODE" deletes the
# hand-added export block:
#
#     set(MX_LINK_LIBS       ${MX_LINK_LIBS}       PARENT_SCOPE)
#     set(MX_Application_Src ${MX_Application_Src} PARENT_SCOPE)
#     set(STM32_Drivers_Src  ${STM32_Drivers_Src}  PARENT_SCOPE)
#
# Symptoms when deleted (hit for real on 2026-10-10):
#   1) configure fails outright:
#        CMake Error at Bootloader/CMakeLists.txt:61 (add_library):
#          No SOURCES given to target: STM32_Drivers_Boot
#      (the Bootloader's -Os HAL copy cannot see STM32_Drivers_Src)
#   2) app_a / app_b / app_c also fail, because the root CMakeLists'
#      add_slot_app() consumes ${MX_Application_Src} and ${MX_LINK_LIBS}.
#
# Idempotent: exits 0 without touching the file if all three exports are present.
#
# USAGE (from anywhere; the script locates the project root itself):
#     powershell -ExecutionPolicy Bypass -File tools\restore_after_cubemx.ps1
#     & .\tools\restore_after_cubemx.ps1          # if already in DP83848\

[CmdletBinding()]
param(
    [string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot)
)

$ErrorActionPreference = 'Stop'

$target = Join-Path $ProjectRoot 'cmake/stm32cubemx/CMakeLists.txt'
if (-not (Test-Path -LiteralPath $target)) {
    throw "Cannot find $target -- is ProjectRoot correct? (got: $ProjectRoot)"
}

$anchor = '# Interface library for includes and symbols'

$exports = @(
    'set(MX_LINK_LIBS ${MX_LINK_LIBS} PARENT_SCOPE)',
    'set(MX_Application_Src ${MX_Application_Src} PARENT_SCOPE)',
    'set(STM32_Drivers_Src ${STM32_Drivers_Src} PARENT_SCOPE)'
)

# Lines that belong to the block we own (removed before re-inserting, so a
# partially-restored file cannot accumulate duplicate export lines).

$lines = Get-Content -LiteralPath $target

$present = @($exports | Where-Object {
    $needle = $_
    ($lines | Where-Object { $_.Trim() -eq $needle }).Count -gt 0
})

if ($present.Count -eq $exports.Count) {
    Write-Host '[OK] All three PARENT_SCOPE exports present - nothing to restore.' -ForegroundColor Green
    exit 0
}

Write-Host '[!] CubeMX removed the hand-written export block. Missing:' -ForegroundColor Yellow
($exports | Where-Object { $present -notcontains $_ }) | ForEach-Object { Write-Host "      $_" }

# Strip any previous/partial copy of the three export lines before re-inserting.
# Only the export lines themselves are matched (never comment text), so this
# works regardless of how the surrounding banner was last written.
$kept = @($lines | Where-Object {
    $t = $_.Trim()
    -not ($exports -contains $t)
})

# Locate the anchor in the kept lines.
$idx = -1
for ($i = 0; $i -lt $kept.Count; $i++) {
    if ($kept[$i].Trim() -eq $anchor) { $idx = $i; break }
}
if ($idx -lt 0) {
    throw "Anchor not found: '$anchor'. Refusing to guess - inspect $target manually."
}

$block = @(
    '# ============================================================================',
    '# !! The export block below is HAND-WRITTEN. CubeMX "GENERATE CODE" deletes it !!',
    '#',
    '# Symptoms when missing:',
    '#   - app_a / app_b / app_c get an empty MX_Application_Src / MX_LINK_LIBS',
    '#   - Bootloader: "No SOURCES given to target: STM32_Drivers_Boot"',
    '# Restore with: tools/restore_after_cubemx.ps1',
    '# CubeMX only knows the content it generated itself.',
    '# ============================================================================',
    '# Export to parent scope so extra App targets (e.g. Slot B builds) can reuse',
    '# the same CubeMX-generated application sources and link libs.',
    $exports[0],
    $exports[1],
    '# Exported so the Bootloader can build its own -Os copy of the HAL',
    '# (see Bootloader/CMakeLists.txt -> STM32_Drivers_Boot)',
    $exports[2],
    ''
)

$out = @()
if ($idx -gt 0) { $out += $kept[0..($idx - 1)] }
$out += $block
$out += $kept[$idx..($kept.Count - 1)]

Set-Content -LiteralPath $target -Value $out -Encoding ASCII
Write-Host "[OK] Export block restored before '$anchor'." -ForegroundColor Green
Write-Host '     Next: re-run cmake configure + build to verify.' -ForegroundColor Green
